mod mathlib {
    pub fn is_prime(n: u32) -> bool {
        if n < 2 { return false; }
        let mut i = 2;
        while i * i <= n {
            if n % i == 0 { return false; }
            i += 1;
        }
        true
    }
}

fn main() {
    let primes: Vec<u32> = (2..=20).filter(|n| mathlib::is_prime(*n)).collect();
    println!("{:?}", primes);
}

