// 本程序演示三类常见报错的“正确版本”：
//   E0382 使用已移动的值 -> 改为借用
//   E0502 可变与不可变借用冲突 -> 先取值再可变操作
//   E0308 类型不匹配 -> 显式转换

fn sum_len(words: &[String]) -> usize {
    words.iter().map(|w| w.len()).sum()
}

fn main() {
    let words = vec![String::from("rust"), String::from("ownership")];
    // E0382 修复：传引用而非移动
    println!("total_len = {}", sum_len(&words));

    // E0502 修复：先取出长度，结束不可变借用后再可变操作
    let first_len = words[0].len();
    let mut counts = vec![first_len];
    counts.push(words[1].len());
    println!("counts = {:?}", counts);

    // E0308 修复：显式 as 转换
    let ratio = counts[1] as f64 / counts[0] as f64;
    println!("ratio = {:.2}", ratio);
}

