// 单文件版：把单元测试和可运行输出放在一起。
// 真实项目里集成测试位于 tests/ 目录（见 files 映射）。

fn digits_sum(text: &str) -> Option<u32> {
    let mut sum = 0u32;
    let mut seen = false;
    for c in text.chars() {
        if let Some(d) = c.to_digit(10) {
            sum += d;
            seen = true;
        }
    }
    if seen { Some(sum) } else { None }
}

fn main() {
    println!("digits_sum(\"a1b2c3\") = {:?}", digits_sum("a1b2c3"));
    println!("digits_sum(\"abc\")    = {:?}", digits_sum("abc"));
    println!("cargo test 会同时跑单元/集成/文档测试");
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn sums_all_digits() {
        assert_eq!(digits_sum("a1b2c3"), Some(6));
    }

    #[test]
    fn returns_none_without_digits() {
        assert_eq!(digits_sum("abc"), None);
    }
}

