// 单文件：把发布检查清单变成可运行的自检输出。
// 真实发布命令与元数据见 files 映射中的 Cargo.toml。

#[derive(Debug, Clone, Copy, PartialEq)]
enum Bump {
    Major,
    Minor,
    Patch,
}

fn next_version(current: &str, bump: Bump) -> String {
    let mut parts: Vec<u32> = current.split('.').map(|p| p.parse().unwrap_or(0)).collect();
    while parts.len() < 3 {
        parts.push(0);
    }
    match bump {
        Bump::Major => { parts[0] += 1; parts[1] = 0; parts[2] = 0; }
        Bump::Minor => { parts[1] += 1; parts[2] = 0; }
        Bump::Patch => { parts[2] += 1; }
    }
    format!("{}.{}.{}", parts[0], parts[1], parts[2])
}

fn main() {
    let current = "0.1.0";
    println!("patch: {} -> {}", current, next_version(current, Bump::Patch));
    println!("minor: {} -> {}", current, next_version(current, Bump::Minor));
    println!("major: {} -> {}", current, next_version(current, Bump::Major));
    println!("发布前: package --list, test --all-features, doc, publish --dry-run");
}

