#[derive(Debug)]
struct Counter {
    value: i64,
    step: i64,
}

impl Counter {
    // 关联函数：构造器
    fn new(step: i64) -> Self {
        Counter { value: 0, step }
    }

    // &mut self：修改内部状态
    fn tick(&mut self) {
        self.value += self.step;
    }

    // &self：只读访问
    fn value(&self) -> i64 {
        self.value
    }

    // self：消费并转换
    fn into_doubled(self) -> i64 {
        self.value * 2
    }
}

fn main() {
    let mut counter = Counter::new(3);
    counter.tick();
    counter.tick();
    println!("value = {}", counter.value());
    let doubled = counter.into_doubled();
    println!("doubled = {}", doubled);
}

