use std::fmt;

#[derive(Debug, Clone, Copy, PartialEq)]
enum Op {
    Add,
    Sub,
    Mul,
    Div,
}

#[derive(Debug, PartialEq)]
enum CalcError {
    Empty,
    UnknownToken(String),
    DivideByZero,
    TrailingOperand,
}

impl fmt::Display for CalcError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            CalcError::Empty => write!(f, "空表达式"),
            CalcError::UnknownToken(t) => write!(f, "未知 token: {}", t),
            CalcError::DivideByZero => write!(f, "除以零"),
            CalcError::TrailingOperand => write!(f, "表达式以运算符结尾"),
        }
    }
}

fn parse_op(tok: &str) -> Option<Op> {
    match tok {
        "+" => Some(Op::Add),
        "-" => Some(Op::Sub),
        "*" => Some(Op::Mul),
        "/" => Some(Op::Div),
        _ => None,
    }
}

fn apply(acc: f64, op: Op, rhs: f64) -> Result<f64, CalcError> {
    Ok(match op {
        Op::Add => acc + rhs,
        Op::Sub => acc - rhs,
        Op::Mul => acc * rhs,
        Op::Div => {
            if rhs == 0.0 {
                return Err(CalcError::DivideByZero);
            }
            acc / rhs
        }
    })
}

// neg 是一元前缀：对紧随其后的一个数字取负，仍产生一个数字 token，
// 因此完整保留原有“先乘除、后加减”的优先级。
fn normalize(input: &str) -> Result<Vec<String>, CalcError> {
    let toks: Vec<&str> = input.split_whitespace().collect();
    if toks.is_empty() {
        return Err(CalcError::Empty);
    }
    let mut out: Vec<String> = Vec::new();
    let mut i = 0;
    while i < toks.len() {
        if toks[i] == "neg" {
            let raw = toks.get(i + 1).ok_or(CalcError::TrailingOperand)?;
            let n: f64 = raw.parse().map_err(|_| CalcError::UnknownToken(raw.to_string()))?;
            out.push((-n).to_string());
            i += 2;
        } else {
            out.push(toks[i].to_string());
            i += 1;
        }
    }
    Ok(out)
}

fn eval(input: &str) -> Result<f64, CalcError> {
    let tokens = normalize(input)?;
    // 第一趟：先处理乘除
    let mut reduced: Vec<String> = Vec::new();
    let mut i = 0;
    while i < tokens.len() {
        let tok = tokens[i].as_str();
        if let Some(op) = parse_op(tok) {
            if matches!(op, Op::Mul | Op::Div) {
                let lhs: f64 = reduced.pop()
                    .ok_or_else(|| CalcError::UnknownToken(tok.to_string()))?
                    .parse().map_err(|_| CalcError::UnknownToken(tok.to_string()))?;
                let rhs_tok = tokens.get(i + 1).ok_or(CalcError::TrailingOperand)?;
                let rhs: f64 = rhs_tok.parse()
                    .map_err(|_| CalcError::UnknownToken(rhs_tok.to_string()))?;
                reduced.push(apply(lhs, op, rhs)?.to_string());
                i += 2;
                continue;
            }
        }
        reduced.push(tokens[i].clone());
        i += 1;
    }
    // 第二趟：再处理加减
    let mut acc: f64 = reduced.first().ok_or(CalcError::TrailingOperand)?
        .parse().map_err(|_| CalcError::UnknownToken(reduced[0].clone()))?;
    let mut j = 1;
    while j < reduced.len() {
        let op = parse_op(&reduced[j]).ok_or_else(|| CalcError::UnknownToken(reduced[j].clone()))?;
        let rhs: f64 = reduced.get(j + 1).ok_or(CalcError::TrailingOperand)?
            .parse().map_err(|_| CalcError::UnknownToken(reduced[j + 1].clone()))?;
        acc = apply(acc, op, rhs)?;
        j += 2;
    }
    Ok(acc)
}

fn main() {
    let inputs = [
        "2 + 3 * 4",
        "neg 5 + 2",
        "neg 3 * 4",
        "10 / 4 - 1",
        "5 / 0",
        "3 +",
    ];
    for expr in inputs {
        match eval(expr) {
            Ok(v) => println!("{} = {}", expr, v),
            Err(e) => println!("{} -> 错误: {}", expr, e),
        }
    }
}

