fn swap_ends(values: &mut [i32]) {
    // split_at_mut 得到两个不重叠的可变借用
    if values.len() >= 2 {
        let mid = values.len() / 2;
        let (left, right) = values.split_at_mut(mid);
        std::mem::swap(&mut left[0], &mut right[right.len() - 1]);
    }
}

fn main() {
    let mut data = Vec::new();
    let sum = fill_and_sum(&mut data, 5);
    println!("sum = {}, data = {:?}", sum, data);

    swap_ends(&mut data);
    println!("after swap_ends = {:?}", data);
}

