// 错误示范（不可编译）: fn bad() -> &str { &String::from("x") }
// 修复 1: 返回拥有型
fn owned_upper(text: &str) -> String {
    text.to_uppercase()
}

// 修复 2: 把输出生命周期绑定到入参。
// 注意：这里按**字符**而不是字节取尾部，避免在多字节 UTF-8（如中文）上 panic。
fn tail<'a>(text: &'a str, n: usize) -> &'a str {
    let count = text.chars().count();
    if n >= count {
        return text;
    }
    let cut = count - n;
    // char_indices 给出每个字符的字节边界，切点必然落在边界上
    let byte_idx = text.char_indices().nth(cut).map(|(i, _)| i).unwrap_or(text.len());
    &text[byte_idx..]
}

// 修复 3: 结构体改为持有索引而非引用（避免自引用）
struct LineIndex {
    offsets: Vec<usize>,
}

impl LineIndex {
    fn build(text: &str) -> Self {
        let mut offsets = vec![0];
        for (i, b) in text.bytes().enumerate() {
            if b == b'\n' {
                offsets.push(i + 1);
            }
        }
        LineIndex { offsets }
    }

    fn line<'a>(&self, text: &'a str, idx: usize) -> Option<&'a str> {
        let start = *self.offsets.get(idx)?;
        let end = self.offsets.get(idx + 1).copied().unwrap_or(text.len());
        Some(&text[start..end].trim_end_matches('\n'))
    }
}

fn main() {
    println!("owned_upper = {}", owned_upper("abc"));
    println!("tail = {}", tail("abcdef", 3));
    println!("tail(cn) = {}", tail("你好世界", 2));

    let doc = "alpha\nbeta\ngamma";
    let index = LineIndex::build(doc);
    println!("line(1) = {:?}", index.line(doc, 1));
}

