use std::cell::Cell;

struct HitCounter {
    count: Cell<u32>,
}

impl HitCounter {
    fn new() -> Self {
        HitCounter { count: Cell::new(0) }
    }

    // 接收 &self，却仍能修改内部计数
    fn hit(&self) -> u32 {
        let next = self.count.get() + 1;
        self.count.set(next);
        next
    }

    fn value(&self) -> u32 {
        self.count.get()
    }
}

fn main() {
