// 目标: 找到绝对值最大的元素并把它翻倍。
// 直接同时读写会冲突，这里分两阶段。

fn double_max_abs(values: &mut [i32]) -> Option<usize> {
    // 只读阶段: 只记录索引，不保留引用
    let target = values
        .iter()
        .enumerate()
        .max_by_key(|(_, v)| v.abs())
        .map(|(i, _)| i)?;

    // 可变阶段: 用索引修改，只读借用已结束
    values[target] *= 2;
    Some(target)
}

