use std::borrow::Cow;
use std::collections::HashMap;

fn normalize(word: &str) -> Cow<'_, str> {
    if word.chars().any(|c| c.is_uppercase()) {
        Cow::Owned(word.to_lowercase())
    } else {
        Cow::Borrowed(word)
    }
}

fn top_words(text: &str, limit: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<Cow<'_, str>, usize> = HashMap::new();
    for raw in text.split_whitespace() {
        let word = normalize(raw.trim_matches(|c: char| !c.is_alphanumeric()));
        if word.is_empty() {
            continue;
        }
        *counts.entry(word).or_insert(0) += 1;
    }

    let mut pairs: Vec<(String, usize)> = counts
        .into_iter()
        .map(|(w, n)| (w.into_owned(), n))
        .collect();
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(limit);
    pairs
}

fn main() {
    let text = "Rust rust makes systems fast; fast safe code. Rust! safe systems";
    for (word, n) in top_words(text, 4) {
        println!("{}: {}", word, n);
    }
}

