use std::collections::HashMap;

fn char_frequency(text: &str) -> Vec<(char, usize)> {
    let mut counts: HashMap<char, usize> = HashMap::new();
    for c in text.chars().filter(|c| c.is_alphabetic()).flat_map(|c| c.to_lowercase()) {
        *counts.entry(c).or_insert(0) += 1;
    }
    let mut pairs: Vec<(char, usize)> = counts.into_iter().collect();
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs
}

fn main() {
    let freq = char_frequency("Hello, World!");
    for (c, n) in freq.into_iter().take(3) {
        println!("{}: {}", c, n);
    }
}

