// 055 answer: implement Task (not just transition)
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Status {
    Todo,
    Done,
    Archived,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Action {
    Complete,
    Reopen,
    Archive,
}

#[derive(Debug)]
struct Task {
    name: String,
    status: Status,
}

impl Task {
    fn new(name: &str) -> Self {
        Task { name: name.to_string(), status: Status::Todo }
    }

    fn transition(&mut self, action: Action) -> Result<Status, &'static str> {
        let next = match (self.status, action) {
            (Status::Todo, Action::Complete) => Status::Done,
            (Status::Done, Action::Reopen) => Status::Todo,
            (Status::Done, Action::Archive) => Status::Archived,
            (Status::Archived, _) => return Err("已归档不可变"),
            _ => return Err("非法转移"),
        };
        self.status = next;
        Ok(next)
    }
}

fn main() {
    let mut task = Task::new("写文档");
    let ok = task.transition(Action::Complete);
    println!("{} -> {:?}, status = {:?}", task.name, ok, task.status);

    let archived = task.transition(Action::Archive);
    println!("archive -> {:?}, status = {:?}", archived, task.status);

    let bad = task.transition(Action::Reopen);
    println!("reopen  -> {:?}, status = {:?}", bad, task.status);
}

