// 057 answer: `@` binding + `if` guards, with a complete F(整十) branch
fn bucket(score: u32) -> &'static str {
    match score {
        s @ 0..=59 if s % 10 == 0 => {
            let _ = s;
            "F(整十)"
        }
        s @ 0..=59 => {
            let _ = s;
            "F"
        }
        s @ 60..=69 if s % 10 == 0 => {
            let _ = s;
            "D(整十)"
        }
        s @ 60..=69 => {
            let _ = s;
            "D"
        }
        s @ 70..=79 if s % 10 == 0 => {
            let _ = s;
            "C(整十)"
        }
        s @ 70..=79 => {
            let _ = s;
            "C"
        }
        s @ 80..=89 if s % 10 == 0 => {
            let _ = s;
            "B(整十)"
        }
        s @ 80..=89 => {
            let _ = s;
            "B"
        }
        s @ 90..=100 if s % 10 == 0 => {
            let _ = s;
            "A(整十)"
        }
        s @ 90..=100 => {
            let _ = s;
            "A"
        }
        _ => "invalid",
    }
}

fn main() {
    // 断言整十（含 F 段）与非整十都正确
    assert_eq!(bucket(0), "F(整十)");
    assert_eq!(bucket(10), "F(整十)");
