use std::fmt;

#[derive(Debug, PartialEq)]
enum Command {
    Move { dx: i32, dy: i32 },
    Say(String),
    Repeat { times: u32, text: String },
    Quit,
}

#[derive(Debug, PartialEq)]
enum ParseError {
    Empty,
    Unknown(String),
    MissingArgs { command: String, expected: usize, got: usize },
    BadNumber(String),
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParseError::Empty => write!(f, "空命令"),
            ParseError::Unknown(c) => write!(f, "未知命令: {}", c),
            ParseError::MissingArgs { command, expected, got } => {
                write!(f, "{} 需要 {} 个参数, 实际 {}", command, expected, got)
            }
            ParseError::BadNumber(s) => write!(f, "无法解析数字: {}", s),
        }
    }
}

fn parse(input: &str) -> Result<Command, ParseError> {
    let mut parts = input.split_whitespace();
    let name = parts.next().ok_or(ParseError::Empty)?;
    let rest: Vec<&str> = parts.collect();

    match name {
        // quit 不接受任何多余参数
        "quit" => {
            if !rest.is_empty() {
                return Err(ParseError::MissingArgs { command: name.into(), expected: 0, got: rest.len() });
            }
            Ok(Command::Quit)
        }
        "move" => {
            if rest.len() != 2 {
                return Err(ParseError::MissingArgs { command: name.into(), expected: 2, got: rest.len() });
            }
            let dx = rest[0].parse().map_err(|_| ParseError::BadNumber(rest[0].into()))?;
            let dy = rest[1].parse().map_err(|_| ParseError::BadNumber(rest[1].into()))?;
            Ok(Command::Move { dx, dy })
        }
        "say" => {
            if rest.is_empty() {
                return Err(ParseError::MissingArgs { command: name.into(), expected: 1, got: 0 });
            }
            Ok(Command::Say(rest.join(" ")))
        }
        "repeat" => {
            if rest.len() < 2 {
                return Err(ParseError::MissingArgs { command: name.into(), expected: 2, got: rest.len() });
            }
            let times = rest[0].parse().map_err(|_| ParseError::BadNumber(rest[0].into()))?;
            Ok(Command::Repeat { times, text: rest[1..].join(" ") })
        }
        other => Err(ParseError::Unknown(other.into())),
    }
}

fn main() {
    let inputs = [
        "move 3 -4",
        "say hello world",
        "repeat 2 rust",
        "quit",
        "quit now",
        "move 3",
        "move a b",
        "dance",
        "",
    ];
    for input in inputs {
        match parse(input) {
            Ok(cmd) => println!("ok  {:?} => {:?}", input, cmd),
            Err(e) => println!("err {:?} => {}", input, e),
        }
    }
}

