use std::collections::HashMap;

trait Store {
    fn get(&self, key: &str) -> Option<u32>;
    fn set(&mut self, key: &str, value: u32);

    // merge 需要具体类型，故用 Self: Sized 排除出 vtable（见对象安全课）
    fn merge(&mut self, other: &Self)
    where
        Self: Sized,
    {
        for (k, v) in other.entries() {
            self.set(&k, v);
        }
    }

    // 供 merge 默认实现读取的辅助方法（也可被具体类型覆写）
    fn entries(&self) -> Vec<(String, u32)>;
}

struct InMemory {
    map: HashMap<String, u32>,
}

impl InMemory {
    fn new() -> Self {
        InMemory { map: HashMap::new() }
    }
}

impl Store for InMemory {
    fn get(&self, key: &str) -> Option<u32> {
        self.map.get(key).copied()
    }

    fn set(&mut self, key: &str, value: u32) {
        self.map.insert(key.to_string(), value);
    }

    fn entries(&self) -> Vec<(String, u32)> {
        let mut pairs: Vec<(String, u32)> = self.map.iter().map(|(k, v)| (k.clone(), *v)).collect();
        pairs.sort();
        pairs
    }
}

fn main() {
    let mut left = InMemory::new();
    left.set("a", 1);
    left.set("b", 2);

    let mut right = InMemory::new();
    right.set("b", 20);
    right.set("c", 30);

    left.merge(&right); // 真实合并：b 被右侧覆盖，新增 c

    let mut items: Vec<(String, u32)> = left.entries();
    items.sort();
    for (k, v) in items {
        println!("{} = {}", k, v);
    }
    println!("{:?}", left.get("missing"));

    // 仍可作为 trait 对象使用（只调用对象安全的方法）
    let mut stores: Vec<Box<dyn Store>> = vec![Box::new(InMemory::new())];
    stores[0].set("x", 9);
    println!("trait object get(x) = {:?}", stores[0].get("x"));
}

