use std::fmt;
use std::str::FromStr;

#[derive(Debug, PartialEq)]
struct Point {
    x: i32,
    y: i32,
}

impl fmt::Display for Point {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "({}, {})", self.x, self.y)
    }
}

impl FromStr for Point {
    type Err = String;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let inner = s.trim().trim_start_matches('(').trim_end_matches(')');
        let (a, b) = inner.split_once(',').ok_or_else(|| format!("缺少逗号: {}", s))?;
        let x: i32 = a.trim().parse().map_err(|_| format!("非法 x: {}", a))?;
        let y: i32 = b.trim().parse().map_err(|_| format!("非法 y: {}", b))?;
        Ok(Point { x, y })
    }
}

fn main() {
    let p = Point { x: 3, y: -4 };
    let text = p.to_string();
    println!("display = {}", text);

    let parsed: Result<Point, _> = text.parse();
    println!("round-trip = {:?}", parsed);
    println!("equal = {}", parsed.as_ref().map(|q| *q == p).unwrap_or(false));

    let bad: Result<Point, _> = "(1;2)".parse();
    println!("bad = {:?}", bad);
}

