#[derive(Debug, Clone)]
struct TempReading {
    sensor: String,
    celsius: f64,
}

// PartialEq 的契约是【对称性 + 传递性】（并不要求自反；自反是 Eq 的额外要求）。
// 这里做逐字段精确相等：sensor 相等，且 celsius 的二进制位相同（to_bits）。
impl PartialEq for TempReading {
    fn eq(&self, other: &Self) -> bool {
        self.sensor == other.sensor && self.celsius.to_bits() == other.celsius.to_bits()
    }
}

impl Eq for TempReading {}

impl TempReading {
    // 近似相等是“容差比较”，不是等价关系，故用独立方法表达，而不是 PartialEq
    fn approx_eq(&self, other: &Self, tolerance: f64) -> bool {
        self.sensor == other.sensor && (self.celsius - other.celsius).abs() <= tolerance
    }
}

fn main() {
    let a = TempReading { sensor: String::from("s1"), celsius: 20.0 };
    let b = TempReading { sensor: String::from("s1"), celsius: 20.3 };
    let c = TempReading { sensor: String::from("s1"), celsius: 20.6 };
    let d = TempReading { sensor: String::from("s2"), celsius: 20.0 };

    // 精确相等：只有完全相同才为真
    println!("a == b: {}", a == b);
    println!("a == clone: {}", a == a.clone());

    // 容差比较：独立方法，避免破坏 PartialEq 的传递性
    println!("a ~ b (0.5): {}", a.approx_eq(&b, 0.5));
    println!("b ~ c (0.5): {}", b.approx_eq(&c, 0.5));
    println!("a ~ c (0.5): {}", a.approx_eq(&c, 0.5));
    println!("a ~ d (0.5): {}", a.approx_eq(&d, 0.5));
}

