trait NumExt {
    fn clamp_between(&self, lo: Self, hi: Self) -> Self;
}

impl<T: PartialOrd + Copy> NumExt for T {
    fn clamp_between(&self, lo: Self, hi: Self) -> Self {
        let v = *self;
        if v < lo {
            lo
        } else if v > hi {
            hi
        } else {
            v
        }
    }
}

