trait Codec {
    fn name(&self) -> &'static str;
    fn encode(&self, record: &Record) -> String;
}

#[derive(Debug)]
struct Record {
    id: u32,
    name: String,
    note: String,
    active: bool,
}

// 完整 JSON 字符串转义：引号、反斜杠、常见控制字符，其余控制字符用 \u00XX 表示。
fn json_escape(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{08}' => out.push_str("\\b"),
            '\u{0c}' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out
}

// RFC 4180 风格 CSV 字段转义：含逗号/引号/换行时用双引号包裹，内部引号翻倍。
fn csv_escape(s: &str) -> String {
    if s.contains(',') || s.contains('"') || s.contains('\n') || s.contains('\r') {
        format!("\"{}\"", s.replace('"', "\"\""))
    } else {
        s.to_string()
    }
}

// key=value 也需转义分隔符，避免值里的 ';' / '=' 破坏结构。
fn kv_escape(s: &str) -> String {
    s.replace('\\', "\\\\").replace(';', "\\;").replace('=', "\\=")
}

struct JsonCodec;
struct KeyValueCodec;
struct CsvCodec;

impl Codec for JsonCodec {
    fn name(&self) -> &'static str {
        "json"
    }
    fn encode(&self, r: &Record) -> String {
        format!(
            "{{\"id\":{},\"name\":\"{}\",\"note\":\"{}\",\"active\":{}}}",
            r.id, json_escape(&r.name), json_escape(&r.note), r.active
        )
    }
}

impl Codec for KeyValueCodec {
    fn name(&self) -> &'static str {
        "kv"
    }
    fn encode(&self, r: &Record) -> String {
        format!(
            "id={};name={};note={};active={}",
            r.id,
            kv_escape(&r.name),
            kv_escape(&r.note),
            r.active
        )
    }
}

impl Codec for CsvCodec {
    fn name(&self) -> &'static str {
        "csv"
    }
    fn encode(&self, r: &Record) -> String {
        format!(
            "{},{},{},{}",
            r.id, csv_escape(&r.name), csv_escape(&r.note), r.active
        )
    }
}

fn registry() -> Vec<Box<dyn Codec>> {
    vec![Box::new(JsonCodec), Box::new(KeyValueCodec), Box::new(CsvCodec)]
}

fn encode_with(registry: &[Box<dyn Codec>], name: &str, record: &Record) -> Option<String> {
    registry
        .iter()
        .find(|c| c.name() == name)
        .map(|c| c.encode(record))
}

fn main() {
    // 含中文、引号、反斜杠、换行、逗号、制表符与分号的记录
    let record = Record {
        id: 7,
        name: String::from("a\"b\\c"),
        note: String::from("行1\n行2, 带\"引号\"\t与中文; 分隔=符"),
        active: true,
    };
    let reg = registry();
    for name in ["json", "kv", "csv", "yaml"] {
        match encode_with(&reg, name, &record) {
            Some(text) => println!("{:<5} => {}", name, text),
            None => println!("{:<5} => 未注册", name),
        }
    }
}

